// THE ENVELOPE (design V-A). Collapses the N rows into ONE item. Without this, a day with 9
// stuck cases would run everything that follows 9 times -- Telegram included, which
// would send 9 messages. It is the real failure that cost a rebuild of the orchestrator.
const findings = $input.all()
  .map(i => i.json)
  .filter(f => f && f.finding);

return [{ json: { findings } }];

// Joins the two envelopes and computes the counters. The counters ALWAYS go into the
// message, complete; the only thing that is capped is the enumeration (design V-R5).
const errors   = $input.all().map(i => i.json).filter(f => f && f.finding);
const findings = $('Sends Envelope').first().json.findings ?? [];

const of = (c) => findings.filter(f => f.finding === c);

const unnotified = errors.filter(e => e.finding === 'error_unnotified');
const errors24h  = Number(errors.find(e => e.finding === 'errors_24h')?.ref ?? 0);
const mark       = errors.find(e => e.finding === 'last_backup')?.ref ?? '';

// The mark is '<ISO> | <rows> | <object key>'. If it does not exist, the backup never ran.
let backup = { status: 'NO RECORD', hours: null, rows: null };
if (mark) {
  const [iso, rows] = String(mark).split(' | ');
  const hours = Math.round(DateTime.now().diff(DateTime.fromISO(iso), 'hours').hours);
  backup = { status: hours > 24 ? 'STALE' : 'ok', hours, rows };
}

const alternation = of('alternation');

return [{ json: {
  date: DateTime.now().setZone('America/Costa_Rica').toFormat('dd/MM/yyyy'),
  pending:            of('pending'),
  ambiguous_expired:  of('ambiguous_expired'),
  unconfirmed:        of('unconfirmed'),
  failed_24h:         of('failed_24h'),
  failed_no_code:     of('failed_no_code'),
  alternation_ok:     alternation.filter(a => String(a.detail).includes('| OK')),
  alternation_bad:    alternation.filter(a => String(a.detail).includes('REPEATED')),
  unnotified,
  errors24h,
  backup,
} }];

const d = $input.first().json;

// INV-15: EVERYTHING that comes from the database is escaped. Keys carry underscores
// and error_message is raw channel text; with parse_mode an alert can fall over
// because of its own content, which is exactly what the invariant forbids.
const esc = (s) => String(s ?? '')
  .replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');

// design V-R5: Telegram cuts at 4096 characters. The COUNTERS always go in, complete;
// what gets truncated is the enumeration, which can be looked up in the database.
const CAP = 10;
const block = (title, rows, fmt) => {
  if (!rows.length) return '';
  const body = rows.slice(0, CAP).map(fmt).join('\n');
  const rest = rows.length > CAP ? `\n... and ${rows.length - CAP} more` : '';
  return `\n\n<b>${esc(title)} (${rows.length})</b>\n${body}${rest}`;
};

const line = (f) =>
  `- ${esc(f.unique_key)} (${esc(f.last_name)}, milestone ${esc(f.milestone)}) - ${f.age_hours} h` +
  (f.ycloud_id ? `\n  id: ${esc(f.ycloud_id)}` : '') +
  (f.detail ? `\n  ${esc(f.detail)}` : '');

// Alerts are what calls for action; the rest is a report. The difference is not one of
// style: a list gets skimmed, an alert gets handled.
const alerts = [];
if (d.ambiguous_expired.length) alerts.push(`${d.ambiguous_expired.length} expired ambiguous send(s): the confirmation is not coming anymore`);
if (d.failed_no_code.length)    alerts.push(`${d.failed_no_code.length} failed send(s) WITHOUT an error code`);
if (d.alternation_bad.length)   alerts.push(`${d.alternation_bad.length} case(s) of REPEATED alternation`);
if (d.unnotified.length)        alerts.push(`${d.unnotified.length} stored error(s) that were NOT notified`);
if (d.backup.status !== 'ok')   alerts.push(`Backup: ${d.backup.status}`);

const backupTxt = d.backup.status === 'NO RECORD'
  ? 'NO RECORD'
  : `${d.backup.hours} h ago - ${d.backup.rows} rows${d.backup.status === 'STALE' ? ' - STALE' : ''}`;

let text =
  `<b>DAILY WATCH - ${esc(d.date)}</b>\n\n` +
  (alerts.length
    ? `<b>ATTENTION</b>\n${alerts.map(a => `- ${esc(a)}`).join('\n')}\n\n`
    : `Nothing that requires action.\n\n`) +
  `Pending: ${d.pending.length}\n` +
  `Expired ambiguous: ${d.ambiguous_expired.length}\n` +
  `Sent but unconfirmed: ${d.unconfirmed.length}\n` +
  `Failed 24 h: ${d.failed_24h.length} (no code: ${d.failed_no_code.length})\n` +
  `Errors 24 h: ${d.errors24h} (not notified: ${d.unnotified.length})\n` +
  `Backup: ${esc(backupTxt)}`;

text += block('Pending', d.pending, line);
text += block('Expired ambiguous', d.ambiguous_expired, line);
text += block('Sent but unconfirmed', d.unconfirmed, line);
text += block('Failed in the last 24 h', d.failed_24h, line);
text += block('Failed WITHOUT code', d.failed_no_code, line);
text += block('Defective alternation', d.alternation_bad, line);
text += block('Verified alternation (V10)', d.alternation_ok, line);
text += block('Errors not notified', d.unnotified,
  (e) => `- #${esc(e.ref)} ${esc(e.workflow)} / ${esc(e.node)} (${esc(e.occurred)})\n  ${esc(e.message)}`);

// Last safety net in case something overflowed anyway: cut before Telegram's hard
// limit, so the alert arrives truncated instead of not arriving at all.
if (text.length > 3900) text = text.slice(0, 3900) + '\n\n[report truncated]';

return [{ json: { text } }];
